/* minimal-purify — DOMPurify 的极简替代（项目内用，防 LLM 输出 XSS）。
 * 规则：仅保留白名单标签，剔除 on* 事件属性，href 仅放行 http/https/mailto，
 * 注释与未知节点一律移除。接口兼容 DOMPurify.sanitize(html) -> string。
 */
"use strict";
(function () {
  const ALLOWED_TAGS = new Set([
    "P", "DIV", "SPAN", "BR", "A", "STRONG", "B", "EM", "I", "U",
    "UL", "OL", "LI", "CODE", "PRE", "BLOCKQUOTE",
    "H1", "H2", "H3", "H4", "H5", "H6", "TABLE", "THEAD", "TBODY", "TR", "TH", "TD",
  ]);

  function sanitize(html) {
    if (typeof html !== "string") return "";
    const template = document.createElement("template");
    template.innerHTML = html;

    const walk = (parent) => {
      for (const node of [...parent.childNodes]) {
        if (node.nodeType === Node.TEXT_NODE) continue;
        if (node.nodeType !== Node.ELEMENT_NODE) {
          parent.removeChild(node);
          continue;
        }
        if (!ALLOWED_TAGS.has(node.tagName)) {
          // 非白名单标签：保留其文本子节点，剥掉标签本身
          while (node.firstChild) parent.insertBefore(node.firstChild, node);
          parent.removeChild(node);
          continue;
        }
        for (const attr of [...node.attributes]) {
          const name = attr.name.toLowerCase();
          if (name.startsWith("on")) node.removeAttribute(attr.name);
          if (name === "href" && !/^(https?:|mailto:)/i.test(attr.value || "")) {
            node.removeAttribute(attr.name);
          }
          if (name === "style") node.removeAttribute(attr.name);
        }
        walk(node);
      }
    };

    walk(template.content);
    return template.innerHTML;
  }

  window.DOMPurify = window.DOMPurify || { sanitize: sanitize };
})();
